import React, { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer, DataStateHandler } from 'components';

import { PERFORMANCE_AND_BREAKDOWN_OVERTIME_TITLE_I18N_ID } from '../../constants';
import {
  usePerformanceAndBreakdownSectionData,
  usePerformanceAndBreakdownSectionUi,
} from '../../hooks';
import { LineBarChartsGrid } from '../LineBarChartsGrid';
import {
  StyledBodyContainer,
  StyledChartsWrapper,
} from './OvertimeSection.styles';

const SKELETON_PROPS = {
  height: '320px',
  width: '100%',
  length: 1,
  borderRadius: 'none' as const,
};

interface OvertimeSectionProps {
  kpi: string | undefined;
  dataTestId?: string;
}

export const OvertimeSection: React.FC<OvertimeSectionProps> = ({
  kpi,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const { view, data } = usePerformanceAndBreakdownSectionData('overtime');
  const { measure, stateMessage } = usePerformanceAndBreakdownSectionUi(
    kpi,
    view,
  );

  const gridDataTestId = useMemo(
    () => (dataTestId ? `${dataTestId}-line-bar-grid` : 'line-bar-grid'),
    [dataTestId],
  );

  return (
    <BasicContainer
      header={{
        title: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_OVERTIME_TITLE_I18N_ID,
        }),
        measure,
        titleSize: 'H4',
      }}
      layout={{
        border: 'small',
        shadow: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
      dataTestId={dataTestId}
    >
      <DataStateHandler
        loading={view === 'loading'}
        error={view === 'error'}
        empty={view === 'empty' || !data || !!data.empty}
        dataTestId={dataTestId ? `${dataTestId}-state` : undefined}
        message={stateMessage}
        skeletonProps={SKELETON_PROPS}
      >
        {view === 'ready' && data ? (
          <StyledBodyContainer>
            <StyledChartsWrapper>
              <LineBarChartsGrid data={data} dataTestId={gridDataTestId} />
            </StyledChartsWrapper>
          </StyledBodyContainer>
        ) : null}
      </DataStateHandler>
    </BasicContainer>
  );
};
